### 1. Validación de Esquemas Zod (Cliente / Servidor)
Para el flujo comercial de supermercado (venta rápida, báscula, múltiples medios de pago y generación de tiquete POS / Factura Electrónica), se requiere un contrato de datos idéntico en ambos extremos para evitar discrepancias en montos, impuestos y retenciones.

```typescript
// src/schemas/supermarket-commercial.schema.ts
import { z } from 'zod';

export const ZodSupermarketItemSchema = z.object({
  product_id: z.string().uuid("ID de producto inválido"),
  sku: z.string().min(1, "SKU requerido"),
  quantity: z.number().positive("La cantidad debe ser mayor a 0"),
  unit_price: z.number().min(0, "El precio unitario no puede ser negativo"),
  tax_rate: z.number().min(0).max(100, "Tasa de impuesto inválida"),
  discount_amount: z.number().min(0, "El descuento no puede ser negativo").default(0),
  is_weighed: z.boolean().default(false),
  tare_weight: z.number().min(0).optional(),
});

export const ZodSupermarketOrderSchema = z.object({
  tenant_id: z.string().uuid("Tenant ID inválido (RLS obligatorio)"),
  register_id: z.string().uuid("ID de caja registradora inválido"),
  cashier_id: z.string().uuid("ID de cajero inválido"),
  customer_id: z.string().uuid("ID de cliente inválido").optional(),
  items: z.array(ZodSupermarketItemSchema).min(1, "La orden debe contener al menos un ítem"),
  payments: z.array(
    z.object({
      method: z.enum(['CASH', 'CREDIT_CARD', 'DEBIT_CARD', 'TRANSFER', 'NEQUI_DAVIPLATA']),
      amount: z.number().positive("El monto de pago debe ser positivo"),
      reference: z.string().optional(),
    })
  ).min(1, "Debe registrarse al menos un medio de pago"),
  subtotal: z.number().min(0),
  total_taxes: z.number().min(0),
  total_amount: z.number().positive("El total debe ser mayor a cero"),
  dian_sync: z.boolean().default(true),
});

export type SupermarketOrderInput = z.infer<typeof ZodSupermarketOrderSchema>;
```

