### 2. Matriz de Pruebas (Vitest + Playwright)

#### A. Pruebas Unitarias e Integración (Vitest)
Se validarán los cálculos financieros, redondeos y el aislamiento por `tenant_id` mediante RLS en Supabase.

```typescript
// src/tests/unit/supermarket-calculations.test.ts
import { describe, it, expect } from 'vitest';
import { ZodSupermarketOrderSchema } from '../../schemas/supermarket-commercial.schema';

describe('SPEC-047: Flujo Comercial Supermercado - Cálculos y Zod', () => {
  it('Debe rechazar órdenes con montos negativos o sin ítems', () => {
    const invalidOrder = {
      tenant_id: 'a0000000-0000-0000-0000-000000000001',
      register_id: 'b0000000-0000-0000-0000-000000000002',
      cashier_id: 'c0000000-0000-0000-0000-000000000003',
      items: [],
      payments: [{ method: 'CASH', amount: 10000 }],
      subtotal: 0,
      total_taxes: 0,
      total_amount: -50, // Inválido
    };

    const result = ZodSupermarketOrderSchema.safeParse(invalidOrder);
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.issues.some(i => i.path.includes('total_amount'))).toBe(true);
      expect(result.error.issues.some(i => i.path.includes('items'))).toBe(true);
    }
  });

  it('Debe validar correctamente una transacción completa de supermercado con IVA', () => {
    const validOrder = {
      tenant_id: 'a0000000-0000-0000-0000-000000000001',
      register_id: 'b0000000-0000-0000-0000-000000000002',
      cashier_id: 'c0000000-0000-0000-0000-000000000003',
      items: [
        {
          product_id: 'd0000000-0000-0000-0000-000000000004',
          sku: 'SAL-001',
          quantity: 2.5, // Kilos (Báscula)
          unit_price: 20000,
          tax_rate: 19,
          is_weighed: true,
        }
      ],
      payments: [
        { method: 'CASH', amount: 60000 }
      ],
      subtotal: 50000,
      total_taxes: 9500,
      total_amount: 59500,
    };

    const result = ZodSupermarketOrderSchema.safeParse(validOrder);
    expect(result.success).toBe(true);
  });
});
```

#### B. Pruebas End-to-End (Playwright)
Validación del flujo crítico en interfaz de usuario (POS Supermercado): Selección de productos, pesaje simulado, procesamiento de pago mixto y generación de factura con validación DIAN.

```typescript
// e2e/supermarket-pos-flow.spec.ts
import { test, expect } from '@playwright/test';

test.describe('SPEC-047: E2E POS Supermercado y Facturación DIAN', () => {
  test.beforeEach(async ({ page }) => {
    // Simular login de cajero multi-tenant
    await page.goto('/login');
    await page.fill('input[name="email"]', 'cajero.super@pezcaderia.com');
    await page.fill('input[name="password"]', 'SecurePassword123!');
    await page.click('button[type="submit"]');
    await page.waitForURL('/pos/supermarket');
  });

  test('Debe completar una venta por peso (báscula) y emitir tiquete POS', async ({ page }) => {
    // 1. Buscar producto de pesaje (ej. Salmón fresco)
    await page.fill('input[data-testid="product-search"]', 'Salmón Fresco');
    await page.click('[data-testid="product-card-salmon"]');

    // 2. Verificar que se activa el modal o integración de báscula
    const scaleModal = page.locator('[data-testid="scale-weight-display"]');
    await expect(scaleModal).toBeVisible();

    // Simular lectura de báscula (1.45 kg)
    await page.fill('input[data-testid="manual-weight-input"]', '1.45');
    await page.click('button:has-text("Confirmar Peso")');

    // 3. Verificar adición al carrito con cálculo correcto
    const cartItem = page.locator('[data-testid="cart-item-salmon"]');
    await expect(cartItem).toContainText('1.45 kg');

    // 4. Procesar Pago (Efectivo)
    await page.click('button:has-text("Pagar")');
    await page.selectOption('select[data-testid="payment-method"]', 'CASH');
    await page.fill('input[data-testid="cash-received"]', '100000');
    await page.click('button:has-text("Finalizar Transacción")');

    // 5. Verificar éxito y sincronización DIAN
    const successModal = page.locator('[data-testid="pos-success-receipt"]');
    await expect(successModal).toBeVisible();
    await expect(page.locator('[data-testid="dian-status-badge"]')).toHaveText('Sincronizado DIAN');
  });
});
```

